create type public.change_type as enum ('STANDARD','NORMAL','EMERGENCY'); create type public.change_status as enum ('DRAFT','ASSESSMENT','AWAITING_APPROVAL','APPROVED','IMPLEMENTING','IMPLEMENTED','FAILED','CANCELLED');
create sequence public.change_number_sequence start 1; create or replace function public.next_change_number() returns text language plpgsql volatile set search_path=public as $$ begin return format('CHG-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.change_number_sequence')::text,6,'0')); end; $$;
create table public.changes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,change_number text not null unique default public.next_change_number(),change_type public.change_type not null,status public.change_status not null default 'DRAFT',title text not null check(length(trim(title)) between 5 and 240),description text not null check(length(trim(description)) between 10 and 10000),justification text not null check(length(trim(justification)) between 10 and 10000),risk_score smallint not null check(risk_score between 1 and 25),implementation_plan text not null check(length(trim(implementation_plan)) between 10 and 10000),test_plan text not null check(length(trim(test_plan)) between 10 and 10000),rollback_plan text not null check(length(trim(rollback_plan)) between 10 and 10000),planned_start timestamptz,planned_end timestamptz,requested_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(planned_end is null or planned_start is null or planned_end>planned_start));
create index changes_org_status_idx on public.changes(organization_id,status,created_at desc);create trigger changes_updated before update on public.changes for each row execute function public.set_updated_at();alter table public.changes enable row level security;create policy "management reads changes" on public.changes for select to authenticated using(public.has_ticket_management_role(organization_id));
create or replace function public.create_change_from_problem(target_problem_id uuid,target_type public.change_type,target_title text,target_description text,target_justification text,target_risk smallint,target_implementation text,target_test text,target_rollback text,target_start timestamptz default null,target_end timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$ declare p public.problems%rowtype; change_id uuid;begin select * into p from public.problems where id=target_problem_id for update;if p.id is null or not public.has_ticket_management_role(p.organization_id) then raise exception 'CHANGE_NOT_AUTHORIZED';end if;if length(trim(target_title)) not between 5 and 240 or length(trim(target_description)) not between 10 and 10000 or length(trim(target_justification)) not between 10 and 10000 or target_risk not between 1 and 25 or length(trim(target_implementation)) not between 10 and 10000 or length(trim(target_test)) not between 10 and 10000 or length(trim(target_rollback)) not between 10 and 10000 then raise exception 'CHANGE_INVALID_INPUT';end if;insert into public.changes(organization_id,change_type,title,description,justification,risk_score,implementation_plan,test_plan,rollback_plan,planned_start,planned_end,requested_by) values(p.organization_id,target_type,trim(target_title),trim(target_description),trim(target_justification),target_risk,trim(target_implementation),trim(target_test),trim(target_rollback),target_start,target_end,auth.uid()) returning id into change_id;insert into public.entity_relationships(organization_id,source_entity_type,source_entity_id,target_entity_type,target_entity_id,relationship_type,reason,created_by) values(p.organization_id,'PROBLEM',p.id,'CHANGE',change_id,'RESOLVED_BY','GMUD criada a partir do problema.',auth.uid());insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(p.organization_id,auth.uid(),'CHANGE_CREATED','change',change_id,jsonb_build_object('problem_id',p.id,'type',target_type,'risk_score',target_risk),'WEB');return change_id;end;$$;
revoke all on function public.create_change_from_problem(uuid,public.change_type,text,text,text,smallint,text,text,text,timestamptz,timestamptz) from public;grant execute on function public.create_change_from_problem(uuid,public.change_type,text,text,text,smallint,text,text,text,timestamptz,timestamptz) to authenticated;
